unsafe fn SpawnObjectEventOnReturnToField(objectEventId: u8, x: i16, y: i16) {
    let mut paletteSlot: u8 = 0;
    let mut sprite: *mut Sprite = null_mut();
    let mut spriteTemplate: SpriteTemplate = zeroed();
    let mut spriteFrameImage: SpriteFrameImage = zeroed();
    for i in 0..4u8 {
        if gLinkPlayerObjectEvents[i].active != 0
            && objectEventId == gLinkPlayerObjectEvents[i].objEventId
        {
            return;
        }
    }
    let objectEvent: *mut ObjectEvent = &raw mut gObjectEvents[objectEventId];
    let mut subspriteTables: *mut SubspriteTable = null_mut();
    let graphicsInfo: *mut ObjectEventGraphicsInfo =
        GetObjectEventGraphicsInfo((*objectEvent).graphicsId);
    spriteFrameImage.size = (*graphicsInfo).size;
    CopyObjectGraphicsInfoToSpriteTemplate_WithMovementType(
        (*objectEvent).graphicsId as u16,
        (*objectEvent).movementType as u16,
        &raw mut spriteTemplate,
        &raw mut subspriteTables,
    );
    spriteTemplate.images = &raw mut spriteFrameImage;
    spriteTemplate.paletteTag = TAG_NONE;
    paletteSlot = (*graphicsInfo).paletteSlot();
    if paletteSlot == PALSLOT_PLAYER {
        LoadPlayerObjectReflectionPalette(
            (*graphicsInfo).paletteTag,
            (*graphicsInfo).paletteSlot(),
        );
    } else if paletteSlot == PALSLOT_NPC_SPECIAL {
        LoadSpecialObjectReflectionPalette(
            (*graphicsInfo).paletteTag,
            (*graphicsInfo).paletteSlot(),
        );
    } else if paletteSlot >= 16 {
        paletteSlot -= 16;
        _PatchObjectPalette((*graphicsInfo).paletteTag, paletteSlot);
    }
    spriteTemplate.paletteTag = TAG_NONE;
    let i: u8 = CreateSprite(&raw mut spriteTemplate, 0, 0, 0);
    if i != MAX_SPRITES {
        sprite = &raw mut gSprites[i];
        GetMapCoordsFromSpritePos(
            x + (*objectEvent).currentCoords.x,
            y + (*objectEvent).currentCoords.y,
            &raw mut (*sprite).x,
            &raw mut (*sprite).y,
        );
        (*sprite).centerToCornerVecX = -(((*graphicsInfo).width >> 1) as i8);
        (*sprite).centerToCornerVecY = -(((*graphicsInfo).height >> 1) as i8);
        (*sprite).x += 8;
        (*sprite).y += 16 + (*sprite).centerToCornerVecY as i16;
        (*sprite).images = (*graphicsInfo).images;
        if (*objectEvent).movementType == MOVEMENT_TYPE_PLAYER {
            SetPlayerAvatarObjectEventIdAndObjectId(objectEventId, i);
            (*objectEvent).warpArrowSpriteId = CreateWarpArrowSprite();
        }
        if !subspriteTables.is_null() {
            SetSubspriteTables(sprite, subspriteTables);
        }
        (*sprite).oam.set_paletteNum(paletteSlot as u16);
        (*sprite).set_coordOffsetEnabled(TRUE as u16);
        (*sprite).data[sObjEventId] = objectEventId as i16;
        (*objectEvent).spriteId = i;
        if (*objectEvent).inanimate() == 0 && (*objectEvent).movementType != MOVEMENT_TYPE_PLAYER {
            StartSpriteAnim(
                sprite,
                GetFaceDirectionAnimNum((*objectEvent).facingDirection() as u8),
            );
        }
        ResetObjectEventFldEffData(objectEvent);
        SetObjectSubpriorityByElevation((*objectEvent).previousElevation(), sprite, 1);
    }
}
unsafe fn ResetObjectEventFldEffData(objectEvent: *mut ObjectEvent) {
    (*objectEvent).set_singleMovementActive(FALSE as u32);
    (*objectEvent).set_triggerGroundEffectsOnMove(TRUE as u32);
    (*objectEvent).set_hasShadow(FALSE as u32);
    (*objectEvent).set_hasReflection(FALSE as u32);
    (*objectEvent).set_inShortGrass(FALSE as u32);
    (*objectEvent).set_inShallowFlowingWater(FALSE as u32);
    (*objectEvent).set_inSandPile(FALSE as u32);
    (*objectEvent).set_inHotSprings(FALSE as u32);
    ObjectEventClearHeldMovement(objectEvent);
}
