pub unsafe fn ObjectEventSetGraphicsId(objectEvent: *mut ObjectEvent, graphicsId: u8) {
    let mut paletteSlot: u8 = 0;
    let graphicsInfo: *mut ObjectEventGraphicsInfo = GetObjectEventGraphicsInfo(graphicsId);
    let sprite: *mut Sprite = &raw mut gSprites[(*objectEvent).spriteId];
    paletteSlot = (*graphicsInfo).paletteSlot();
    if paletteSlot == PALSLOT_PLAYER {
        PatchObjectPalette((*graphicsInfo).paletteTag, (*graphicsInfo).paletteSlot());
    } else if paletteSlot == PALSLOT_NPC_SPECIAL {
        LoadSpecialObjectReflectionPalette(
            (*graphicsInfo).paletteTag,
            (*graphicsInfo).paletteSlot(),
        );
    } else if paletteSlot >= 16 {
        paletteSlot -= 16;
        _PatchObjectPalette((*graphicsInfo).paletteTag, paletteSlot);
    }
    (*sprite).oam.set_shape((*(*graphicsInfo).oam).shape());
    (*sprite).oam.set_size((*(*graphicsInfo).oam).size());
    (*sprite).images = (*graphicsInfo).images;
    (*sprite).anims = (*graphicsInfo).anims;
    (*sprite).subspriteTables = (*graphicsInfo).subspriteTables;
    (*sprite).oam.set_paletteNum(paletteSlot as u16);
    (*objectEvent).set_inanimate((*graphicsInfo).inanimate() as u32);
    (*objectEvent).graphicsId = graphicsId;
    SetSpritePosToMapCoords(
        (*objectEvent).currentCoords.x,
        (*objectEvent).currentCoords.y,
        &raw mut (*sprite).x,
        &raw mut (*sprite).y,
    );
    (*sprite).centerToCornerVecX = -(((*graphicsInfo).width >> 1) as i8);
    (*sprite).centerToCornerVecY = -(((*graphicsInfo).height >> 1) as i8);
    (*sprite).x += 8;
    (*sprite).y += 16 + (*sprite).centerToCornerVecY as i16;
    if (*objectEvent).trackedByCamera() != 0 {
        CameraObjectReset();
    }
}
