pub unsafe fn TryOverrideObjectEventTemplateCoords(localId: u8, mapNum: u8, mapGroup: u8) {
    let mut objectEventId: u8 = 0;
    if TryGetObjectEventIdByLocalIdAndMap(localId, mapNum, mapGroup, &raw mut objectEventId) == 0 {
        OverrideTemplateCoordsForObjectEvent(&raw mut gObjectEvents[objectEventId]);
    }
}
pub unsafe fn OverrideSecretBaseDecorationSpriteScript(
    localId: u8,
    mapNum: u8,
    mapGroup: u8,
    decorationCategory: u8,
) {
    let mut objectEventId: u8 = 0;
    if TryGetObjectEventIdByLocalIdAndMap(localId, mapNum, mapGroup, &raw mut objectEventId) == 0 {
        match decorationCategory {
            DECORCAT_DOLL => {
                OverrideObjectEventTemplateScript(
                    &raw mut gObjectEvents[objectEventId],
                    (*crate::asmdata::SecretBase_EventScript_DollInteract.cast::<CArray<u8, 0>>())
                        .as_ptr()
                        .cast_mut(),
                );
            }
            DECORCAT_CUSHION => {
                OverrideObjectEventTemplateScript(
                    &raw mut gObjectEvents[objectEventId],
                    (*crate::asmdata::SecretBase_EventScript_CushionInteract
                        .cast::<CArray<u8, 0>>())
                    .as_ptr()
                    .cast_mut(),
                );
            }
            _ => {}
        }
    }
}
pub unsafe fn InitObjectEventPalettes(reflectionType: u8) {
    FreeAndReserveObjectSpritePalettes();
    sCurrentSpecialObjectPaletteTag.set(OBJ_EVENT_PAL_TAG_NONE);
    sCurrentReflectionType.set(reflectionType);
    if reflectionType == 1 {
        PatchObjectPaletteRange(
            sObjectPaletteTagSets[sCurrentReflectionType.get()],
            PALSLOT_PLAYER,
            6,
        );
        gReservedSpritePaletteCount = 8;
    } else {
        PatchObjectPaletteRange(
            sObjectPaletteTagSets[sCurrentReflectionType.get()],
            PALSLOT_PLAYER,
            10,
        );
    }
}
pub unsafe fn GetObjectPaletteTag(palSlot: u8) -> u16 {
    if palSlot < PALSLOT_NPC_SPECIAL {
        return *sObjectPaletteTagSets[sCurrentReflectionType.get()].at(palSlot);
    }
    let mut i: u8 = 0;
    while sSpecialObjectReflectionPaletteSets[i].tag != OBJ_EVENT_PAL_TAG_NONE {
        if sSpecialObjectReflectionPaletteSets[i].tag == sCurrentSpecialObjectPaletteTag.get() {
            return *sSpecialObjectReflectionPaletteSets[i]
                .data
                .at(sCurrentReflectionType.get());
        }
        i += 1;
    }
    OBJ_EVENT_PAL_TAG_NONE
}
