pub unsafe fn ObjectEventIsTrainerAndCloseToPlayer(objectEvent: *mut ObjectEvent) -> u8 {
    let mut playerX: i16 = 0;
    let mut playerY: i16 = 0;
    if TestPlayerAvatarFlags(PLAYER_AVATAR_FLAG_DASH) == 0 {
        return FALSE;
    }
    if (*objectEvent).trainerType != TRAINER_TYPE_NORMAL
        && (*objectEvent).trainerType != TRAINER_TYPE_BURIED
    {
        return FALSE;
    }
    PlayerGetDestCoords(&raw mut playerX, &raw mut playerY);
    let objX: i16 = (*objectEvent).currentCoords.x;
    let objY: i16 = (*objectEvent).currentCoords.y;
    let minX: i16 = objX - (*objectEvent).trainerRange_berryTreeId as i16;
    let minY: i16 = objY - (*objectEvent).trainerRange_berryTreeId as i16;
    let maxX: i16 = objX + (*objectEvent).trainerRange_berryTreeId as i16;
    let maxY: i16 = objY + (*objectEvent).trainerRange_berryTreeId as i16;
    if minX > playerX || maxX < playerX || minY > playerY || maxY < playerY {
        return FALSE;
    }
    TRUE
}
pub fn GetVectorDirection(dx: i16, dy: i16, absdx: i16, absdy: i16) -> u8 {
    let mut direction: u8 = 0;
    if absdx > absdy {
        direction = DIR_EAST;
        if dx < 0 {
            direction = DIR_WEST;
        }
    } else {
        direction = DIR_SOUTH;
        if dy < 0 {
            direction = DIR_NORTH;
        }
    }
    direction
}
pub fn GetLimitedVectorDirection_SouthNorth(dx: i16, dy: i16, absdx: i16, absdy: i16) -> u8 {
    let mut direction: u8 = DIR_SOUTH;
    if dy < 0 {
        direction = DIR_NORTH;
    }
    direction
}
pub fn GetLimitedVectorDirection_WestEast(dx: i16, dy: i16, absdx: i16, absdy: i16) -> u8 {
    let mut direction: u8 = DIR_EAST;
    if dx < 0 {
        direction = DIR_WEST;
    }
    direction
}
pub fn GetLimitedVectorDirection_WestNorth(dx: i16, dy: i16, absdx: i16, absdy: i16) -> u8 {
    let mut direction: u8 = GetVectorDirection(dx, dy, absdx, absdy);
    if direction == DIR_SOUTH {
        direction = GetLimitedVectorDirection_WestEast(dx, dy, absdx, absdy);
        if direction == DIR_EAST {
            direction = DIR_NORTH;
        }
    } else if direction == DIR_EAST {
        direction = GetLimitedVectorDirection_SouthNorth(dx, dy, absdx, absdy);
        if direction == DIR_SOUTH {
            direction = DIR_NORTH;
        }
    }
    direction
}
