pub unsafe fn TryGetTrainerEncounterDirection(
    objectEvent: *mut ObjectEvent,
    movementType: u8,
) -> u8 {
    let mut dx: i16 = 0;
    let mut dy: i16 = 0;
    if ObjectEventIsTrainerAndCloseToPlayer(objectEvent) == 0 {
        return DIR_NONE;
    }
    PlayerGetDestCoords(&raw mut dx, &raw mut dy);
    dx -= (*objectEvent).currentCoords.x;
    dy -= (*objectEvent).currentCoords.y;
    let mut absdx: i16 = dx;
    let mut absdy: i16 = dy;
    if absdx < 0 {
        absdx = -absdx;
    }
    if absdy < 0 {
        absdy = -absdy;
    }
    gGetVectorDirectionFuncs[movementType].unwrap_unchecked()(dx, dy, absdx, absdy)
}
