pub unsafe fn MoveNextDirectionInSequence(
    objectEvent: *mut ObjectEvent,
    sprite: *mut Sprite,
    route: *mut u8,
) -> u8 {
    if (*objectEvent).directionSequenceIndex == 3
        && (*objectEvent).initialCoords.x == (*objectEvent).currentCoords.x
        && (*objectEvent).initialCoords.y == (*objectEvent).currentCoords.y
    {
        (*objectEvent).directionSequenceIndex = 0;
    }
    SetObjectEventDirection(
        objectEvent,
        *route.at((*objectEvent).directionSequenceIndex),
    );
    let mut movementActionId: u8 =
        GetWalkNormalMovementAction((*objectEvent).movementDirection() as u32);
    let mut collision: u8 =
        GetCollisionInDirection(objectEvent, (*objectEvent).movementDirection() as u8);
    if collision == COLLISION_OUTSIDE_RANGE {
        (*objectEvent).directionSequenceIndex += 1;
        SetObjectEventDirection(
            objectEvent,
            *route.at((*objectEvent).directionSequenceIndex),
        );
        movementActionId = GetWalkNormalMovementAction((*objectEvent).movementDirection() as u32);
        collision = GetCollisionInDirection(objectEvent, (*objectEvent).movementDirection() as u8);
    }
    if collision != 0 {
        movementActionId =
            GetWalkInPlaceNormalMovementAction((*objectEvent).facingDirection() as u32);
    }
    ObjectEventSetSingleMovement(objectEvent, sprite, movementActionId);
    (*objectEvent).set_singleMovementActive(TRUE as u32);
    (*sprite).data[sTypeFuncId] = 2;
    TRUE
}
