unsafe fn GetStepAnimTable(anims: *mut *mut AnimCmd) -> *mut StepAnimTable {
    let mut stepTable: *mut StepAnimTable = sStepAnimTables.as_ptr().cast_mut();
    while !(*stepTable).anims.is_null() {
        if (*stepTable).anims == anims {
            return stepTable;
        }
        stepTable = stepTable.at(1);
    }
    null_mut()
}
pub unsafe fn SetStepAnimHandleAlternation(
    objectEvent: *mut ObjectEvent,
    sprite: *mut Sprite,
    animNum: u8,
) {
    let mut stepTable: *mut StepAnimTable = null_mut();
    if (*objectEvent).inanimate() == 0 {
        (*sprite).animNum = animNum;
        stepTable = GetStepAnimTable((*sprite).anims);
        if !stepTable.is_null() {
            if (*sprite).animCmdIndex == (*stepTable).animPos[0] {
                (*sprite).animCmdIndex = (*stepTable).animPos[3];
            } else if (*sprite).animCmdIndex == (*stepTable).animPos[1] {
                (*sprite).animCmdIndex = (*stepTable).animPos[2];
            }
        }
        SeekSpriteAnim(sprite, (*sprite).animCmdIndex);
    }
}
pub unsafe fn SetStepAnim(objectEvent: *mut ObjectEvent, sprite: *mut Sprite, animNum: u8) {
    let mut stepTable: *mut StepAnimTable = null_mut();
    if (*objectEvent).inanimate() == 0 {
        let mut animPos: u8 = 0;
        (*sprite).animNum = animNum;
        stepTable = GetStepAnimTable((*sprite).anims);
        if !stepTable.is_null() {
            animPos = (*stepTable).animPos[1];
            if (*sprite).animCmdIndex <= (*stepTable).animPos[0] {
                animPos = (*stepTable).animPos[0];
            }
            SeekSpriteAnim(sprite, animPos);
        }
    }
}
pub fn GetDirectionToFace(x: i16, y: i16, targetX: i16, targetY: i16) -> u8 {
    if x > targetX {
        return DIR_WEST;
    }
    if x < targetX {
        return DIR_EAST;
    }
    if y > targetY {
        return DIR_NORTH;
    }
    DIR_SOUTH
}
