unsafe fn GetCollisionInDirection(objectEvent: *mut ObjectEvent, direction: u8) -> u8 {
    let mut x: i16 = (*objectEvent).currentCoords.x;
    let mut y: i16 = (*objectEvent).currentCoords.y;
    MoveCoords(direction, &raw mut x, &raw mut y);
    GetCollisionAtCoords(objectEvent, x, y, direction as u32)
}
pub unsafe fn GetCollisionAtCoords(objectEvent: *mut ObjectEvent, x: i16, y: i16, dir: u32) -> u8 {
    let direction: u8 = dir as u8;
    if IsCoordOutsideObjectEventMovementRange(objectEvent, x, y) != 0 {
        return COLLISION_OUTSIDE_RANGE;
    } else if MapGridGetCollisionAt(x as i32, y as i32) != 0
        || GetMapBorderIdAt(x as i32, y as i32) == CONNECTION_INVALID
        || IsMetatileDirectionallyImpassable(objectEvent, x, y, direction) != 0
    {
        return COLLISION_IMPASSABLE;
    } else if (*objectEvent).trackedByCamera() != 0
        && CanCameraMoveInDirection(direction as i32) == 0
    {
        return COLLISION_IMPASSABLE;
    } else if IsElevationMismatchAt((*objectEvent).currentElevation(), x, y) != 0 {
        return COLLISION_ELEVATION_MISMATCH;
    } else if DoesObjectCollideWithObjectAt(objectEvent, x, y) != 0 {
        return COLLISION_OBJECT_EVENT;
    }
    COLLISION_NONE
}
pub unsafe fn GetCollisionFlagsAtCoords(
    objectEvent: *mut ObjectEvent,
    x: i16,
    y: i16,
    direction: u8,
) -> u8 {
    let mut flags: u8 = 0;
    if IsCoordOutsideObjectEventMovementRange(objectEvent, x, y) != 0 {
        flags |= 1;
    }
    if MapGridGetCollisionAt(x as i32, y as i32) != 0
        || GetMapBorderIdAt(x as i32, y as i32) == CONNECTION_INVALID
        || IsMetatileDirectionallyImpassable(objectEvent, x, y, direction) != 0
        || (*objectEvent).trackedByCamera() != 0 && CanCameraMoveInDirection(direction as i32) == 0
    {
        flags |= 2;
    }
    if IsElevationMismatchAt((*objectEvent).currentElevation(), x, y) != 0 {
        flags |= 4;
    }
    if DoesObjectCollideWithObjectAt(objectEvent, x, y) != 0 {
        flags |= 8;
    }
    flags
}
unsafe fn IsCoordOutsideObjectEventMovementRange(
    objectEvent: *mut ObjectEvent,
    x: i16,
    y: i16,
) -> u8 {
    let mut left: i16 = 0;
    let mut right: i16 = 0;
    let mut top: i16 = 0;
    let mut bottom: i16 = 0;
    if (*objectEvent).range.rangeX() != 0 {
        left = (*objectEvent).initialCoords.x - (*objectEvent).range.rangeX() as i16;
        right = (*objectEvent).initialCoords.x + (*objectEvent).range.rangeX() as i16;
        if left > x || right < x {
            return TRUE;
        }
    }
    if (*objectEvent).range.rangeY() != 0 {
        top = (*objectEvent).initialCoords.y - (*objectEvent).range.rangeY() as i16;
        bottom = (*objectEvent).initialCoords.y + (*objectEvent).range.rangeY() as i16;
        if top > y || bottom < y {
            return TRUE;
        }
    }
    FALSE
}
unsafe fn IsMetatileDirectionallyImpassable(
    objectEvent: *mut ObjectEvent,
    x: i16,
    y: i16,
    direction: u8,
) -> u8 {
    if gOppositeDirectionBlockedMetatileFuncs[direction as i32 - 1].unwrap_unchecked()(
        (*objectEvent).currentMetatileBehavior,
    ) != 0
        || gDirectionBlockedMetatileFuncs[direction as i32 - 1].unwrap_unchecked()(
            MapGridGetMetatileBehaviorAt(x as i32, y as i32) as u8,
        ) != 0
    {
        return TRUE;
    }
    FALSE
}
unsafe fn DoesObjectCollideWithObjectAt(objectEvent: *mut ObjectEvent, x: i16, y: i16) -> u8 {
    let mut curObject: *mut ObjectEvent = null_mut();
    for i in 0..OBJECT_EVENTS_COUNT {
        curObject = &raw mut gObjectEvents[i];
        if (*curObject).active() != 0
            && curObject != objectEvent
            && ((*curObject).currentCoords.x == x && (*curObject).currentCoords.y == y
                || (*curObject).previousCoords.x == x && (*curObject).previousCoords.y == y)
            && AreElevationsCompatible(
                (*objectEvent).currentElevation(),
                (*curObject).currentElevation(),
            ) != 0
        {
            return TRUE;
        }
    }
    FALSE
}
pub unsafe fn IsBerryTreeSparkling(localId: u8, mapNum: u8, mapGroup: u8) -> u8 {
    let mut objectEventId: u8 = 0;
    if TryGetObjectEventIdByLocalIdAndMap(localId, mapNum, mapGroup, &raw mut objectEventId) == 0
        && gSprites[gObjectEvents[objectEventId].spriteId].data[sBerryTreeFlags] as i32
            & BERRY_FLAG_SPARKLING as i32
            != 0
    {
        return TRUE;
    }
    FALSE
}
pub unsafe fn SetBerryTreeJustPicked(localId: u8, mapNum: u8, mapGroup: u8) {
    let mut objectEventId: u8 = 0;
    if TryGetObjectEventIdByLocalIdAndMap(localId, mapNum, mapGroup, &raw mut objectEventId) == 0 {
        gSprites[gObjectEvents[objectEventId].spriteId].data[sBerryTreeFlags] |=
            BERRY_FLAG_JUST_PICKED;
    }
}
pub unsafe fn MoveCoords(direction: u8, x: *mut i16, y: *mut i16) {
    *x += sDirectionToVectors[direction].x;
    *y += sDirectionToVectors[direction].y;
}
unsafe fn MoveCoordsInMapCoordIncrement(direction: u8, x: *mut i16, y: *mut i16) {
    *x += sDirectionToVectors[direction].x << 4;
    *y += sDirectionToVectors[direction].y << 4;
}
unsafe fn MoveCoordsInDirection(dir: u32, x: *mut i16, y: *mut i16, deltaX: i16, deltaY: i16) {
    let direction: u8 = dir as u8;
    let dx2: i16 = deltaX as u16 as i16;
    let dy2: i16 = deltaY as u16 as i16;
    if sDirectionToVectors[direction].x > 0 {
        *x += dx2;
    }
    if sDirectionToVectors[direction].x < 0 {
        *x -= dx2;
    }
    if sDirectionToVectors[direction].y > 0 {
        *y += dy2;
    }
    if sDirectionToVectors[direction].y < 0 {
        *y -= dy2;
    }
}
pub unsafe fn GetMapCoordsFromSpritePos(x: i16, y: i16, destX: *mut i16, destY: *mut i16) {
    *destX = (x - (*gSaveBlock1Ptr).pos.x) << 4;
    *destY = (y - (*gSaveBlock1Ptr).pos.y) << 4;
    *destX -= gTotalCameraPixelOffsetX as i16;
    *destY -= gTotalCameraPixelOffsetY as i16;
}
pub unsafe fn SetSpritePosToMapCoords(mapX: i16, mapY: i16, destX: *mut i16, destY: *mut i16) {
    let mut dx: i16 = -(gTotalCameraPixelOffsetX as i16) - gFieldCamera.x as i16;
    let mut dy: i16 = -(gTotalCameraPixelOffsetY as i16) - gFieldCamera.y as i16;
    if gFieldCamera.x > 0 {
        dx += 16;
    }
    if gFieldCamera.x < 0 {
        dx -= 16;
    }
    if gFieldCamera.y > 0 {
        dy += 16;
    }
    if gFieldCamera.y < 0 {
        dy -= 16;
    }
    *destX = ((mapX - (*gSaveBlock1Ptr).pos.x) << 4) + dx;
    *destY = ((mapY - (*gSaveBlock1Ptr).pos.y) << 4) + dy;
}
pub unsafe fn SetSpritePosToOffsetMapCoords(x: *mut i16, y: *mut i16, dx: i16, dy: i16) {
    SetSpritePosToMapCoords(*x, *y, x, y);
    *x += dx;
    *y += dy;
}
unsafe fn GetObjectEventMovingCameraOffset(x: *mut i16, y: *mut i16) {
    *x = 0;
    *y = 0;
    if gFieldCamera.x > 0 {
        *x += 1;
    }
    if gFieldCamera.x < 0 {
        *x -= 1;
    }
    if gFieldCamera.y > 0 {
        *y += 1;
    }
    if gFieldCamera.y < 0 {
        *y -= 1;
    }
}
