pub unsafe fn InitNpcForMovement(
    objectEvent: *mut ObjectEvent,
    sprite: *mut Sprite,
    direction: u8,
    speed: u8,
) {
    let mut x: i16 = 0;
    let mut y: i16 = 0;
    x = (*objectEvent).currentCoords.x;
    y = (*objectEvent).currentCoords.y;
    SetObjectEventDirection(objectEvent, direction);
    MoveCoords(direction, &raw mut x, &raw mut y);
    ShiftObjectEventCoords(objectEvent, x, y);
    SetSpriteDataForNormalStep(sprite, direction, speed);
    (*sprite).set_animPaused(FALSE);
    if !sLockedAnimObjectEvents.is_null()
        && FindLockedObjectEventIndex(objectEvent) != OBJECT_EVENTS_COUNT
    {
        (*sprite).set_animPaused(TRUE);
    }
    (*objectEvent).set_triggerGroundEffectsOnMove(TRUE as u32);
    (*sprite).data[sActionFuncId] = 1;
}
unsafe fn InitMovementNormal(
    objectEvent: *mut ObjectEvent,
    sprite: *mut Sprite,
    direction: u8,
    speed: u8,
) {
    let mut functions: CArray<Option<unsafe fn(u8) -> u8>, 5> = zeroed();
    memcpy(
        functions.as_mut_ptr() as *mut u8,
        sDirectionAnimFuncsBySpeed.as_ptr().cast_mut() as *mut u8,
        20,
    );
    InitNpcForMovement(objectEvent, sprite, direction, speed);
    SetStepAnimHandleAlternation(
        objectEvent,
        sprite,
        functions[speed].unwrap_unchecked()((*objectEvent).facingDirection() as u8),
    );
}
