unsafe fn InitJump(
    objectEvent: *mut ObjectEvent,
    sprite: *mut Sprite,
    direction: u8,
    distance: u8,
    r#type: u8,
) {
    let mut displacements: CArray<i16, 3> = zeroed();
    memcpy(
        displacements.as_mut_ptr() as *mut u8,
        sJumpInitDisplacements.as_ptr().cast_mut() as *mut u8,
        6,
    );
    let mut x: i16 = 0;
    let mut y: i16 = 0;
    SetObjectEventDirection(objectEvent, direction);
    MoveCoordsInDirection(
        direction as u32,
        &raw mut x,
        &raw mut y,
        displacements[distance],
        displacements[distance],
    );
    ShiftObjectEventCoords(
        objectEvent,
        (*objectEvent).currentCoords.x + x,
        (*objectEvent).currentCoords.y + y,
    );
    SetJumpSpriteData(sprite, direction, distance, r#type);
    (*sprite).data[sActionFuncId] = 1;
    (*sprite).set_animPaused(FALSE);
    (*objectEvent).set_triggerGroundEffectsOnMove(TRUE as u32);
    (*objectEvent).set_disableCoveringGroundEffects(TRUE as u32);
}
unsafe fn InitJumpRegular(
    objectEvent: *mut ObjectEvent,
    sprite: *mut Sprite,
    direction: u8,
    distance: u8,
    r#type: u8,
) {
    InitJump(objectEvent, sprite, direction, distance, r#type);
    SetStepAnimHandleAlternation(
        objectEvent,
        sprite,
        GetMoveDirectionAnimNum((*objectEvent).facingDirection() as u8),
    );
    DoShadowFieldEffect(objectEvent);
}
unsafe fn UpdateJumpAnim(
    objectEvent: *mut ObjectEvent,
    sprite: *mut Sprite,
    callback: Option<unsafe fn(*mut Sprite) -> u8>,
) -> u8 {
    let mut displacements: CArray<i16, 3> = zeroed();
    let mut x: i16 = 0;
    let mut y: i16 = 0;
    memcpy(
        displacements.as_mut_ptr() as *mut u8,
        sJumpDisplacements.as_ptr().cast_mut() as *mut u8,
        6,
    );
    let result: u8 = callback.unwrap_unchecked()(sprite);
    if result == JUMP_HALFWAY && displacements[(*sprite).data[sDistance]] != 0 {
        x = 0;
        y = 0;
        MoveCoordsInDirection(
            (*objectEvent).movementDirection() as u32,
            &raw mut x,
            &raw mut y,
            displacements[(*sprite).data[sDistance]],
            displacements[(*sprite).data[sDistance]],
        );
        ShiftObjectEventCoords(
            objectEvent,
            (*objectEvent).currentCoords.x + x,
            (*objectEvent).currentCoords.y + y,
        );
        (*objectEvent).set_triggerGroundEffectsOnMove(TRUE as u32);
        (*objectEvent).set_disableCoveringGroundEffects(TRUE as u32);
    } else if result == JUMP_FINISHED as u8 {
        ShiftStillObjectEventCoords(objectEvent);
        (*objectEvent).set_triggerGroundEffectsOnStop(TRUE as u32);
        (*objectEvent).set_landingJump(TRUE as u32);
        (*sprite).set_animPaused(TRUE);
    }
    result
}
unsafe fn DoJumpAnimStep(objectEvent: *mut ObjectEvent, sprite: *mut Sprite) -> u8 {
    UpdateJumpAnim(objectEvent, sprite, Some(DoJumpSpriteMovement))
}
unsafe fn DoJumpSpecialAnimStep(objectEvent: *mut ObjectEvent, sprite: *mut Sprite) -> u8 {
    UpdateJumpAnim(objectEvent, sprite, Some(DoJumpSpecialSpriteMovement))
}
unsafe fn DoJumpAnim(objectEvent: *mut ObjectEvent, sprite: *mut Sprite) -> u8 {
    if DoJumpAnimStep(objectEvent, sprite) == JUMP_FINISHED as u8 {
        return TRUE;
    }
    FALSE
}
unsafe fn DoJumpSpecialAnim(objectEvent: *mut ObjectEvent, sprite: *mut Sprite) -> u8 {
    if DoJumpSpecialAnimStep(objectEvent, sprite) == JUMP_FINISHED as u8 {
        return TRUE;
    }
    FALSE
}
unsafe fn DoJumpInPlaceAnim(objectEvent: *mut ObjectEvent, sprite: *mut Sprite) -> u8 {
    'l1: {
        let sw1: u8 = DoJumpAnimStep(objectEvent, sprite);
        let matched = sw1 == 255 || sw1 == JUMP_HALFWAY;
        let mut fall = false;
        if sw1 == 255 {
            return TRUE;
        }
        if sw1 == JUMP_HALFWAY {
            fall = true;
            SetObjectEventDirection(
                objectEvent,
                GetOppositeDirection((*objectEvent).movementDirection() as u8),
            );
            SetStepAnim(
                objectEvent,
                sprite,
                GetMoveDirectionAnimNum((*objectEvent).facingDirection() as u8),
            );
        }
        if fall || !matched {
            return FALSE;
        }
    }
    #[allow(unreachable_code)]
    {
        0
    }
}
