pub unsafe fn MovementAction_FacePlayer_Step0(
    objectEvent: *mut ObjectEvent,
    sprite: *mut Sprite,
) -> u8 {
    let mut playerObjectId: u8 = 0;
    if TryGetObjectEventIdByLocalIdAndMap(LOCALID_PLAYER, 0, 0, &raw mut playerObjectId) == 0 {
        FaceDirection(
            objectEvent,
            sprite,
            GetDirectionToFace(
                (*objectEvent).currentCoords.x,
                (*objectEvent).currentCoords.y,
                gObjectEvents[playerObjectId].currentCoords.x,
                gObjectEvents[playerObjectId].currentCoords.y,
            ),
        );
    }
    (*sprite).data[sActionFuncId] = 1;
    TRUE
}
