pub unsafe fn MovementAction_RevealTrainer_Step0(
    objectEvent: *mut ObjectEvent,
    sprite: *mut Sprite,
) -> u8 {
    if (*objectEvent).movementType == MOVEMENT_TYPE_BURIED {
        SetBuriedTrainerMovement(objectEvent);
        return FALSE;
    }
    if (*objectEvent).movementType != MOVEMENT_TYPE_TREE_DISGUISE
        && (*objectEvent).movementType != MOVEMENT_TYPE_MOUNTAIN_DISGUISE
    {
        (*sprite).data[sActionFuncId] = 2;
        return TRUE;
    }
    StartRevealDisguise(objectEvent);
    (*sprite).data[sActionFuncId] = 1;
    MovementAction_RevealTrainer_Step1(objectEvent, sprite)
}
