unsafe fn UpdateObjectEventVisibility(objectEvent: *mut ObjectEvent, sprite: *mut Sprite) {
    UpdateObjectEventOffscreen(objectEvent, sprite);
    UpdateObjectEventSpriteVisibility(objectEvent, sprite);
}
unsafe fn UpdateObjectEventOffscreen(objectEvent: *mut ObjectEvent, sprite: *mut Sprite) {
    let mut x: u16 = 0;
    let mut y: u16 = 0;
    let mut x2: u16 = 0;
    let mut y2: u16 = 0;
    (*objectEvent).set_offScreen(FALSE as u32);
    let graphicsInfo: *mut ObjectEventGraphicsInfo =
        GetObjectEventGraphicsInfo((*objectEvent).graphicsId);
    if (*sprite).coordOffsetEnabled() != 0 {
        x = (*sprite).x as u16
            + (*sprite).x2 as u16
            + (*sprite).centerToCornerVecX as u16
            + gSpriteCoordOffsetX as u16;
        y = (*sprite).y as u16
            + (*sprite).y2 as u16
            + (*sprite).centerToCornerVecY as u16
            + gSpriteCoordOffsetY as u16;
    } else {
        x = (*sprite).x as u16 + (*sprite).x2 as u16 + (*sprite).centerToCornerVecX as u16;
        y = (*sprite).y as u16 + (*sprite).y2 as u16 + (*sprite).centerToCornerVecY as u16;
    }
    x2 = (*graphicsInfo).width as u16;
    x2 += x;
    y2 = y;
    y2 += (*graphicsInfo).height as u16;
    if x as i16 >= 256 || (x2 as i16) < -16 {
        (*objectEvent).set_offScreen(TRUE as u32);
    }
    if y as i16 >= 176 || (y2 as i16) < -16 {
        (*objectEvent).set_offScreen(TRUE as u32);
    }
}
unsafe fn UpdateObjectEventSpriteVisibility(objectEvent: *mut ObjectEvent, sprite: *mut Sprite) {
    (*sprite).set_invisible(FALSE as u16);
    if (*objectEvent).invisible() != 0 || (*objectEvent).offScreen() != 0 {
        (*sprite).set_invisible(TRUE as u16);
    }
}
