unsafe fn AnimateSpriteInFigure8(sprite: *mut Sprite) -> u8 {
    let mut finished: u8 = FALSE;
    match (*sprite).data[7] {
        0 => {
            (*sprite).x2 += GetFigure8XOffset((*sprite).data[6]);
            (*sprite).y2 += GetFigure8YOffset((*sprite).data[6]);
        }
        1 => {
            (*sprite).x2 -= GetFigure8XOffset(71 - (*sprite).data[6]);
            (*sprite).y2 += GetFigure8YOffset(71 - (*sprite).data[6]);
        }
        2 => {
            (*sprite).x2 -= GetFigure8XOffset((*sprite).data[6]);
            (*sprite).y2 += GetFigure8YOffset((*sprite).data[6]);
        }
        3 => {
            (*sprite).x2 += GetFigure8XOffset(71 - (*sprite).data[6]);
            (*sprite).y2 += GetFigure8YOffset(71 - (*sprite).data[6]);
        }
        _ => {}
    }
    if ({
        (*sprite).data[6] += 1;
        (*sprite).data[6]
    }) == FIGURE_8_LENGTH
    {
        (*sprite).data[6] = 0;
        (*sprite).data[7] += 1;
    }
    if (*sprite).data[7] == 4 {
        (*sprite).y2 = 0;
        (*sprite).x2 = 0;
        finished = TRUE;
    }
    finished
}
