pub(crate) unsafe fn DoJumpSpriteMovement(sprite: *mut Sprite) -> u8 {
    let mut distanceToTime: CArray<i16, 3> = zeroed();
    distanceToTime[0] = 16;
    distanceToTime[1] = 16;
    distanceToTime[2] = 32;
    let mut distanceToShift: CArray<u8, 3> = zeroed();
    distanceToShift[0] = 0;
    distanceToShift[1] = 0;
    distanceToShift[2] = 1;
    let mut result: u8 = 0;
    if (*sprite).data[sDistance] != JUMP_DISTANCE_IN_PLACE as i16 {
        Step1(sprite, (*sprite).data[sDirection] as u8);
    }
    (*sprite).y2 = GetJumpY(
        shr_i32(
            (*sprite).data[6] as i32,
            distanceToShift[(*sprite).data[sDistance]] as u32,
        ) as i16,
        (*sprite).data[sJumpType] as u8,
    );
    (*sprite).data[6] += 1;
    if (*sprite).data[6] == distanceToTime[(*sprite).data[sDistance]] >> 1 {
        result = JUMP_HALFWAY;
    }
    if (*sprite).data[6] >= distanceToTime[(*sprite).data[sDistance]] {
        (*sprite).y2 = 0;
        result = JUMP_FINISHED as u8;
    }
    result
}
pub(crate) unsafe fn DoJumpSpecialSpriteMovement(sprite: *mut Sprite) -> u8 {
    let mut distanceToTime: CArray<i16, 3> = zeroed();
    distanceToTime[0] = 32;
    distanceToTime[1] = 32;
    distanceToTime[2] = 64;
    let mut distanceToShift: CArray<u8, 3> = zeroed();
    distanceToShift[0] = 1;
    distanceToShift[1] = 1;
    distanceToShift[2] = 2;
    let mut result: u8 = 0;
    if (*sprite).data[sDistance] != JUMP_DISTANCE_IN_PLACE as i16
        && (*sprite).data[6] as i32 & 1 == 0
    {
        Step1(sprite, (*sprite).data[sDirection] as u8);
    }
    (*sprite).y2 = GetJumpY(
        shr_i32(
            (*sprite).data[6] as i32,
            distanceToShift[(*sprite).data[sDistance]] as u32,
        ) as i16,
        (*sprite).data[sJumpType] as u8,
    );
    (*sprite).data[6] += 1;
    if (*sprite).data[6] == distanceToTime[(*sprite).data[sDistance]] >> 1 {
        result = JUMP_HALFWAY;
    }
    if (*sprite).data[6] >= distanceToTime[(*sprite).data[sDistance]] {
        (*sprite).y2 = 0;
        result = JUMP_FINISHED as u8;
    }
    result
}
