pub unsafe fn UpdateObjectEventSpriteInvisibility(sprite: *mut Sprite, invisible: u8) {
    let mut x: u16 = 0;
    let mut y: u16 = 0;
    let mut x2: i16 = 0;
    let mut y2: i16 = 0;
    (*sprite).set_invisible(invisible as u16);
    if (*sprite).coordOffsetEnabled() != 0 {
        x = (*sprite).x as u16
            + (*sprite).x2 as u16
            + (*sprite).centerToCornerVecX as u16
            + gSpriteCoordOffsetX as u16;
        y = (*sprite).y as u16
            + (*sprite).y2 as u16
            + (*sprite).centerToCornerVecY as u16
            + gSpriteCoordOffsetY as u16;
    } else {
        x = (*sprite).x as u16 + (*sprite).x2 as u16 + (*sprite).centerToCornerVecX as u16;
        y = (*sprite).y as u16 + (*sprite).y2 as u16 + (*sprite).centerToCornerVecY as u16;
    }
    x2 = x as i16 - ((*sprite).centerToCornerVecX >> 1) as i16;
    y2 = y as i16 - ((*sprite).centerToCornerVecY >> 1) as i16;
    if x as i16 >= 256 || x2 < -16 {
        (*sprite).set_invisible(TRUE as u16);
    }
    if y as i16 >= 176 || y2 < -16 {
        (*sprite).set_invisible(TRUE as u16);
    }
}
